package com.mendes.scheduling_platform.availability; import com.mendes.scheduling_platform.security.TenantContext; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/venues/{venueId}/availabilities") public class AvailabilityController { private final AvailabilityService s; public AvailabilityController(AvailabilityService s){this.s=s;} @GetMapping List<Availability> list(@PathVariable Long venueId){return s.list(TenantContext.getRequired(),venueId);}@PostMapping @PreAuthorize("hasAnyRole('OWNER','MANAGER')") Availability add(@PathVariable Long venueId,@RequestBody Availability a){return s.save(TenantContext.getRequired(),venueId,a);}@DeleteMapping("/{id}") @PreAuthorize("hasAnyRole('OWNER','MANAGER')") void delete(@PathVariable Long venueId,@PathVariable Long id){s.delete(TenantContext.getRequired(),id);} }
